for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];
    float pressureForceX = 0.0f, pressureForceY = 0.0f, pressureForceZ = 0.0f;
    float viscosityForceX = 0.0f, viscosityForceY = 0.0f, viscosityForceZ = 0.0f;
    float density = 0.0f;

    for (size_t j = 0; j < particleCount; ++j) {
        if (i == j) continue;
        Particle& neighbor = particles[j];
        float dx = neighbor.x - p.x;
        float dy = neighbor.y - p.y;
        float dz = neighbor.z - p.z;
        float distSq = dx * dx + dy * dy + dz * dz;
        if (distSq >= h2) continue;

        float dist = std::sqrt(distSq);
        if (dist < 1e-6f) continue;

        float r = dist;
        float invR = 1.0f / r;
        float invH = 1.0f / h;
        float invH2 = invH * invH;
        float q = r * invH;

        // Spiky gradient kernel
        float gradW = 0.0f;
        if (q <= 1.0f) {
            gradW = spikyGrad * invH2 * (1.0f - q) * invR;
        }

        // Spiky Laplacian kernel
        float lapW = 0.0f;
        if (q <= 1.0f) {
            lapW = spikyLap * invH2 * (1.0f - q);
        }

        // Density contribution
        density += neighbor.mass * lapW;

        // Pressure force: -mass * (p.pressure + neighbor.pressure) / (2 * neighbor.density) * gradW
        float pressureSum = p.pressure + neighbor.pressure;
        float densityAvg = (p.density + neighbor.density) * 0.5f;
        if (densityAvg > 1e-6f) {
            float pressureTerm = -mass * pressureSum / (2.0f * densityAvg) * gradW;
            pressureForceX += pressureTerm * dx;
            pressureForceY += pressureTerm * dy;
            pressureForceZ += pressureTerm * dz;
        }

        // Viscosity force: viscosity * mass * (v_neighbor - v_particle) / neighbor.density * gradW
        float dvx = neighbor.vx - p.vx;
        float dvy = neighbor.vy - p.vy;
        float dvz = neighbor.vz - p.vz;
        if (neighbor.density > 1e-6f) {
            float viscosityTerm = viscosity * neighbor.mass * invR * gradW / neighbor.density;
            viscosityForceX += viscosityTerm * dvx;
            viscosityForceY += viscosityTerm * dvy;
            viscosityForceZ += viscosityTerm * dvz;
        }
    }

    p.density = density;
    p.pressureForceX = pressureForceX;
    p.pressureForceY = pressureForceY;
    p.pressureForceZ = pressureForceZ;
    p.viscosityForceX = viscosityForceX;
    p.viscosityForceY = viscosityForceY;
    p.viscosityForceZ = viscosityForceZ;
}

